import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var groups = [{ id: 'trucks', title: 'Грузовики', objects: ['MAZ 5440', 'Volvo FH16'] }, { id: 'vans', title: 'Фургоны', objects: ['GAZ Next'] }];
var ids = ['MAZ 5440', 'Volvo FH16', 'GAZ Next'];
function selection(items, chosen) { var n = items.filter(function (id) { return chosen.includes(id); }).length; return n === 0 ? 'unchecked' : n === items.length ? 'checked' : 'indeterminate'; }
function TreeExample() {
    var open = React.useState({ user: true, trucks: true, vans: false }), chosen = React.useState(['Volvo FH16']);
    function toggle(id, next) { open[1](function (prev) { return Object.assign({}, prev, { [id]: next }); }); }
    function choose(items, next) { chosen[1](function (prev) { var rest = prev.filter(function (id) { return !items.includes(id); }); return next === 'checked' ? rest.concat(items) : rest; }); }
    return <div className={"demo-stack"}>
    <div className={'tree'}>
    <S.DsTreeRow title={'Петров Сергей'} avatar={true} expanded={open[0].user} onToggle={function (next) { toggle('user', next); }} selected={chosen[0].length} total={ids.length} select={selection(ids, chosen[0])} onSelectChange={function (next) { choose(ids, next); }} unread={2}/>
    {open[0].user ? groups.map(function (group) {
            return <React.Fragment key={group.id}>
        <S.DsTreeRow title={group.title} icon={'label'} level={1} expanded={open[0][group.id]} onToggle={function (next) { toggle(group.id, next); }} selected={group.objects.filter(function (id) { return chosen[0].includes(id); }).length} total={group.objects.length} select={selection(group.objects, chosen[0])} onSelectChange={function (next) { choose(group.objects, next); }}/>
        {open[0][group.id] ? <div className={'leaves'}>
        {group.objects.map(function (id) {
                        return <div className={'leaf'} key={id}>
        <span>
        {id}
        </span>
        <S.DsCheckbox state={chosen[0].includes(id) ? 'checked' : 'unchecked'} ariaLabel={'Выбрать: ' + id} onChange={function (next) { choose([id], next); }}/>
        </div>;
                    })}
        </div> : null}
        </React.Fragment>;
        }) : null}
    </div>
    <p className={'cap'} role={'status'}>
    {'Выбрано объектов: ' + chosen[0].length + ' из ' + ids.length}
    </p>
    <p className={'cap'}>
    {'Выбор группы меняет выбор её объектов. Сворачивание сохраняет выбор.'}
    </p>
    </div>;
}
function App() {
    return <div className="dstreerow-example">
    <style>{exampleStyles}</style>
    <TreeExample />
    </div>;
}

const exampleStyles = ".dstreerow-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dstreerow-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dstreerow-example p{margin:0}\n.dstreerow-example .tree{max-width:560px;min-width:0}\n.dstreerow-example .leaves{padding-left:40px}\n.dstreerow-example .leaf{display:flex;align-items:center;gap:var(--ds-gap-sm);min-width:0}\n.dstreerow-example .leaf>span{flex:1;min-width:0}\n.dstreerow-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };

